const Ca = 0.1, Cb = 0.1, Va = 25, Ka = 1.8e-5, pKa = -Math.log10(Ka), Kw = 1e-14;
function pH(Vb) {
  const na = Ca * Va / 1000, nb = Cb * Vb / 1000, Vt = (Va + Vb) / 1000;
  if (Vt <= 0) return 7;
  if (nb < na - 1e-12) {
    const HA = (na - nb) / Vt, Am = nb / Vt;
    if (Am <= 1e-12) return -Math.log10(Math.sqrt(Ka * HA));
    return pKa + Math.log10(Am / HA);
  } else if (Math.abs(nb - na) <= 1e-12) {
    const Am = na / Vt;
    return 14 + Math.log10(Math.sqrt((Kw / Ka) * Am));
  } else {
    return 14 + Math.log10((nb - na) / Vt);
  }
}
